def factorize(n: int) -> List[int]:
    out = []
    n = n
    i = 2
    while i * i <= n:
        while n % i == 0:
            out.append(i)
            n //= i
        i += 1
    if n > 1:
        out.append(n)
    return out

def triples_sum_to_zero(l: list):
    for i in range(len(l)):
        for j in range(i + 1, len(l)):
            for k in range(j + 1, len(l)):
                if l[i] + l[j] + l[k] == 0:
                    return True
    return False

def pairs_sum_to_zero(l):
    for i in range(len(l)):
        for j in range(i + 1, len(l)):
            if l[i] + l[j] == 0:
                return True
    return False

def remove_vowels(text):
    out = []
    for ch in text:
        if ch not in "aeiouAEIOU":
            out.append(ch)
    return "".join(out)

